import copy
from unittest.mock import patch
import router
import service
from models import PayloadError
from routing import handlers, validation


def original(command, payload):
    if command not in ('create', 'update', 'delete'):
        raise ValueError('unknown command: ' + command)
    if not isinstance(payload, dict):
        raise PayloadError('payload must be a dictionary')
    normalized = {}
    if command in ('update', 'delete'):
        identifier = payload.get('id')
        if type(identifier) is not int or identifier <= 0:
            raise PayloadError('id must be positive integer')
        normalized['id'] = identifier
    if command in ('create', 'update'):
        name = payload.get('name')
        if not isinstance(name, str) or not name.strip():
            raise PayloadError('name must be nonempty string')
        normalized['name'] = name.strip()
    if command == 'create':
        return service.create(normalized['name'])
    if command == 'update':
        return service.update(normalized['id'], normalized['name'])
    return service.delete(normalized['id'])


def outcome(fn, command, payload):
    try:
        return ('result', fn(command, payload))
    except Exception as exc:
        return ('error', type(exc), str(exc))

payloads = [None, [], 'x', 0, {}, {'id': 0, 'name': ''}]
for identifier in (None, False, True, -1, 0, 1, 2.0, '2'):
    for name in (None, False, 1, '', '  ', ' A ', '\tB\n'):
        payloads.append({'id': identifier, 'name': name, 'extra': [1]})
count = 0
for command in ('create', 'update', 'delete', 'unknown', '', None, 1, [], {}):
    for payload in payloads:
        before = copy.deepcopy(payload)
        assert outcome(router.dispatch, command, payload) == outcome(original, command, payload)
        assert payload == before
        count += 1
for command in ('create', 'update', 'delete'):
    normalized = {'id': 4, 'name': 'N'}
    sentinel = object()
    with patch.object(validation, 'validate_payload', return_value=normalized) as validate:
        with patch.object(handlers, 'handle_' + command, return_value=sentinel) as handle:
            payload = object()
            assert router.dispatch(command, payload) is sentinel
            validate.assert_called_once_with(command, payload)
            handle.assert_called_once_with(normalized)
    with patch.object(service, command, return_value=sentinel) as call:
        assert getattr(handlers, 'handle_' + command)(normalized) is sentinel
        expected = {'create': ('N',), 'update': (4, 'N'), 'delete': (4,)}[command]
        call.assert_called_once_with(*expected)
payload = {'id': 4, 'name': ' N ', 'extra': 1}
assert validation.validate_payload('update', payload) == {'id': 4, 'name': 'N'}
assert validation.validate_payload('update', payload) is not payload
print(f'Passed {count} behavior comparisons, mutation checks, direct API and delegation checks.')
